static int giant_part_authored(int i){return i<4||i==6||(i<6&&ex.giant.form>=1)||(i>=7&&ex.giant.form>=2);}
static float giant_flex_at(float localY,float tick){Giant*b=&ex.giant;return b->archetype==1?sinf(tick*.075f+localY*.032f)*(1.7f+b->form*.65f):0;}
static void giant_limb_pose(int i,float*x,float*y,int*angle){Giant*b=&ex.giant;float t=b->timer*(.045f+b->form*.008f),side=i&1?1:-1,p=t+(i/2)*.8f,sw=sinf(p);if(i==6){*y+=sinf(t*1.4f)*1.5f;*angle=(int)(sinf(t*.7f)*3);return;}switch(b->archetype){case 0:*x+=side*sw*3;*y+=cosf(p)*4;*angle=(int)(side*(sw*17+4));break;case 1:*x+=side*(3+sw*7);*y+=cosf(p)*7;*angle=(int)(side*(sw*24+5));break;case 2:*x+=side*sw*5;*y+=cosf(p)*6;*angle=(int)(side*sw*21);break;case 3:*y+=sw*5;*angle=(int)(side*(sw*13+4));break;case 5:*x+=side*sw*8;*y+=cosf(p)*9;*angle=(int)(side*(sw*25+5));break;}if(b->attackClock>=60&&b->attackClock<200)*y-=3*fmaxf(0,sinf(b->timer*.6f+i));*x+=giant_flex_at(*y-100,b->timer);}
static float giant_damage_fraction(void){Giant*b=&ex.giant;if(b->archetype==4)return b->parts[6].maxHp>0?fmaxf(0,1-b->parts[6].hp/(float)b->parts[6].maxHp):0;float damage=0,max=0;for(int i=0;i<9;i++)if(i!=6&&giant_part_authored(i)&&(b->parts[i].hp>0||b->woundForm[i]==b->form)){damage+=b->parts[i].maxHp-b->parts[i].hp;max+=b->parts[i].maxHp;}float core=b->parts[6].maxHp>0?1-b->parts[6].hp/(float)b->parts[6].maxHp:0;return fminf(1,fmaxf(0,core*.6f+(max>0?damage/max:0)*.4f));}
static int giant_damage_until(void){int until=0;for(int i=0;i<9;i++)if(giant_part_authored(i)&&ex.giant.parts[i].damageUntil>until)until=ex.giant.parts[i].damageUntil;return until;}
